namespace Challenge;public record Cart(decimal Subtotal,bool Vip,string Coupon);public interface IPromotion{decimal Apply(Cart cart,decimal current);}public sealed class PricingEngine(IEnumerable<IPromotion> rules){readonly IReadOnlyList<IPromotion> all=rules.ToList();public decimal Total(Cart cart){var value=all.Aggregate(cart.Subtotal,(v,r)=>r.Apply(cart,v));return Math.Max(0,value);}}
